def validate(text):
    closers = {')': '(', ']': '[', '}': '{'}
    stack = []
    for i, ch in enumerate(text):
        if ch in '([{':
            stack.append(i)
        elif ch in closers:
            if not stack:
                return False
            top = stack[-1]
            if text[top] != closers[ch]:
                return False
            stack.pop()
    return not stack

def repair(text):
    chars = list(text)
    pairs = {'(': ')', '[': ']', '{': '}'}
    openers = {')': '(', ']': '[', '}': '{'}
    stack = []
    i = 0
    while i < len(chars):
        ch = chars[i]
        if ch in pairs:
            stack.append(i)
        elif ch in openers:
            if not stack:
                chars.insert(i, openers[ch])
                i += 1
            else:
                top = stack[-1]
                expected = pairs[chars[top]]
                if ch != expected:
                    chars[i] = expected
                stack.pop()
        i += 1
    while stack:
        chars.append(pairs[chars[stack.pop()]])
    return ''.join(chars)
